/**
 * @summary Get notes uploaded by a specific user
 */
export const getGetUserNotesUrl = (id: number) => {
  return `/api/users/${id}/notes`;
};

export const getUserNotes = async (
  id: number,
  options?: RequestInit,
): Promise<Note[]> => {
  return customFetch<Note[]>(getGetUserNotesUrl(id), {
    ...options,
    method: "GET",
  });
};

export const getGetUserNotesQueryKey = (id: number) => {
  return [`/api/users/${id}/notes`] as const;
};

export const getGetUserNotesQueryOptions = <
  TData = Awaited<ReturnType<typeof getUserNotes>>,
  TError = ErrorType<unknown>,
>(
  id: number,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof getUserNotes>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey = queryOptions?.queryKey ?? getGetUserNotesQueryKey(id);

  const queryFn: QueryFunction<Awaited<ReturnType<typeof getUserNotes>>> = ({
    signal,
  }) => getUserNotes(id, { signal, ...requestOptions });

  return {
    queryKey,
    queryFn,
    enabled: !!id,
    ...queryOptions,
  } as UseQueryOptions<
    Awaited<ReturnType<typeof getUserNotes>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

export type GetUserNotesQueryResult = NonNullable<
  Awaited<ReturnType<typeof getUserNotes>>
>;
export type GetUserNotesQueryError = ErrorType<unknown>;

/**
 * @summary Get notes uploaded by a specific user
 */

export function useGetUserNotes<
  TData = Awaited<ReturnType<typeof getUserNotes>>,
  TError = ErrorType<unknown>,
>(
  id: number,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof getUserNotes>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
): UseQueryResult<TData, TError> & { queryKey: QueryKey } {
  const queryOptions = getGetUserNotesQueryOptions(id, options);

  const query = useQuery(queryOptions) as UseQueryResult<TData, TError> & {
    queryKey: QueryKey;
  };

  return { ...query, queryKey: queryOptions.queryKey };
}
